     1→/**
     2→ * MCP Server Manager
     3→ *
     4→ * Manages the lifecycle of the embedded MCP server within the Electron main process.
     5→ * Provides utilities for conditionally starting the MCP server based on environment variables.
     6→ *
     7→ * Usage:
     8→ *   import { initializeMCPServer } from './mcp-manager.js';
     9→ *
    10→ *   app.whenReady().then(() => {
    11→ *     initializeMCPServer();  // Starts if ELECTRON_MCP_ENABLED=true
    12→ *   });
    13→ *
    14→ * Environment Variables:
    15→ *   - ELECTRON_MCP_ENABLED: Set to "true" to enable MCP server (default: disabled)
    16→ *   - ELECTRON_MCP_LOG_LEVEL: Log verbosity (debug|info|warn|error, default: info)
    17→ *
    18→ * @see MCP_ARCHITECTURE_DESIGN_1.2.md
    19→ * @see SECURITY_REQUIREMENTS_AND_CONTEXT_ISOLATION_1.3.md
    20→ */
    21→
    22→import { app } from 'electron';
    23→import { ElectronMCPServer } from './mcp-server.js';
    24→
    25→// ============================================================================
    26→// Constants
    27→// ============================================================================
    28→
    29→/** Environment variable to enable MCP server */
    30→const MCP_ENABLED_ENV = 'ELECTRON_MCP_ENABLED';
    31→
    32→/** Environment variable for log level */
    33→const MCP_LOG_LEVEL_ENV = 'ELECTRON_MCP_LOG_LEVEL';
    34→
    35→/** Default log level */
    36→const DEFAULT_LOG_LEVEL = 'info';
    37→
    38→// ============================================================================
    39→// State
    40→// ============================================================================
    41→
    42→/** Global MCP server instance */
    43→let mcpServer: ElectronMCPServer | null = null;
    44→
    45→/** Whether the MCP server is currently running */
    46→let isRunning = false;
    47→
    48→// ============================================================================
    49→// Utility Functions
    50→// ============================================================================
    51→
    52→/** Valid log levels for MCP server */
    53→const VALID_LOG_LEVELS = ['debug', 'info', 'warn', 'error'] as const;
    54→type LogLevel = typeof VALID_LOG_LEVELS[number];
    55→
    56→/**
    57→ * Validate a log level value
    58→ * @param level - Log level to validate
    59→ * @returns true if valid, false otherwise
    60→ */
    61→function isValidLogLevel(level: string): level is LogLevel {
    62→  return VALID_LOG_LEVELS.includes(level as LogLevel);
    63→}
    64→
    65→/**
    66→ * Check if MCP server should be enabled
    67→ * @returns true if ELECTRON_MCP_ENABLED is set to "true"
    68→ */
    69→export function isMCPServerEnabled(): boolean {
    70→  const enabled = process.env[MCP_ENABLED_ENV];
    71→  if (enabled === undefined || enabled === '') {
    72→    return false;
    73→  }
    74→  const normalized = enabled.toLowerCase().trim();
    75→  if (normalized !== 'true' && normalized !== 'false') {
    76→    console.warn(`[MCP] Invalid value for ${MCP_ENABLED_ENV}: "${enabled}". Expected "true" or "false". Defaulting to false.`);
    77→    return false;
    78→  }
    79→  return normalized === 'true';
    80→}
    81→
    82→/**
    83→ * Get the configured log level for MCP server
    84→ * @returns Log level from environment or default
    85→ * @throws Error if log level is invalid
    86→ */
    87→export function getMCPLogLevel(): string {
    88→  const level = process.env[MCP_LOG_LEVEL_ENV];
    89→  if (!level) {
    90→    return DEFAULT_LOG_LEVEL;
    91→  }
    92→  const normalized = level.toLowerCase().trim();
    93→  if (!isValidLogLevel(normalized)) {
    94→    console.warn(`[MCP] Invalid log level: "${level}". Valid values: ${VALID_LOG_LEVELS.join(', ')}. Using default: ${DEFAULT_LOG_LEVEL}`);
    95→    return DEFAULT_LOG_LEVEL;
    96→  }
    97→  return normalized;
    98→}
    99→
   100→/**
   101→ * Check if MCP server is currently running
   102→ * @returns true if server is active
   103→ */
   104→export function isMCPServerRunning(): boolean {
   105→  return isRunning;
   106→}
   107→
   108→/**
   109→ * Get the MCP server instance (if running)
   110→ * @returns MCP server instance or null
   111→ */
   112→export function getMCPServer(): ElectronMCPServer | null {
   113→  return mcpServer;
   114→}
   115→
   116→// ============================================================================
   117→// MCP Server Lifecycle
   118→// ============================================================================
   119→
   120→/**
   121→ * Initialize the MCP server if enabled via environment variable.
   122→ *
   123→ * This function should be called during Electron app initialization (after app.whenReady()).
   124→ * It checks the ELECTRON_MCP_ENABLED environment variable and starts the server if set to "true".
   125→ *
   126→ * Usage:
   127→ *   app.whenReady().then(() => {
   128→ *     initializeMCPServer();
   129→ *     createWindow();
   130→ *   });
   131→ *
   132→ * The server runs in the same process as Electron (embedded mode) and uses stdio transport
   133→ * for communication with the Claude Agent SDK via stdin/stdout.
   134→ *
   135→ * @returns Promise that resolves when server is started or skipped
   136→ * @throws Error if server startup fails
   137→ */
   138→export async function initializeMCPServer(): Promise<void> {
   139→  // Check if MCP server is enabled
   140→  if (!isMCPServerEnabled()) {
   141→    console.log('[MCP] Server not enabled (set ELECTRON_MCP_ENABLED=true to activate)');
   142→    return;
   143→  }
   144→
   145→  // Check if already running
   146→  if (isRunning) {
   147→    console.warn('[MCP] Server already running, skipping initialization');
   148→    return;
   149→  }
   150→
   151→  // Set log level from environment
   152→  const logLevel = getMCPLogLevel();
   153→  if (logLevel !== DEFAULT_LOG_LEVEL) {
   154→    process.env[MCP_LOG_LEVEL_ENV] = logLevel;
   155→    console.log(`[MCP] Log level set to: ${logLevel}`);
   156→  }
   157→
   158→  try {
   159→    console.log('[MCP] Initializing embedded MCP server...');
   160→    console.log('[MCP] Mode: embedded (stdio transport)');
   161→    console.log('[MCP] Transport: stdio (stdin/stdout)');
   162→
   163→    // Create MCP server instance
   164→    mcpServer = new ElectronMCPServer();
   165→
   166→    // Start the server
   167→    await mcpServer.start();
   168→
   169→    isRunning = true;
   170→    console.log('[MCP] ✅ Server started successfully');
   171→    console.log('[MCP] Waiting for JSON-RPC requests via stdin/stdout...');
   172→
   173→  } catch (error) {
   174→    const errorMessage = error instanceof Error ? error.message : String(error);
   175→    console.error('[MCP] ❌ Failed to start server:', errorMessage);
   176→
   177→    if (error instanceof Error && process.env[MCP_LOG_LEVEL_ENV] === 'debug') {
   178→      console.error('[MCP] Stack trace:', error.stack);
   179→    }
   180→
   181→    throw error;
   182→  }
   183→}
   184→
   185→/**
   186→ * Stop the MCP server gracefully.
   187→ *
   188→ * This function is called automatically when the Electron app quits.
   189→ * It closes the stdio transport and cleans up resources.
   190→ *
   191→ * @returns Promise that resolves when server is stopped
   192→ */
   193→export async function stopMCPServer(): Promise<void> {
   194→  if (!isRunning || !mcpServer) {
   195→    return;
   196→  }
   197→
   198→  console.log('[MCP] Stopping server...');
   199→
   200→  try {
   201→    await mcpServer.stop();
   202→  } catch (error) {
   203→    console.error('[MCP] Error during shutdown:', error);
   204→  } finally {
   205→    mcpServer = null;
   206→    isRunning = false;
   207→  }
   208→}
   209→
   210→// ============================================================================
   211→// App Lifecycle Integration
   212→// ============================================================================
   213→
   214→/**
   215→ * Setup automatic MCP server lifecycle management.
   216→ *
   217→ * This function integrates the MCP server with Electron's app lifecycle:
   218→ * - Starts server when app is ready (if enabled)
   219→ * - Stops server when app quits
   220→ *
   221→ * Usage:
   222→ *   setupMCPLifecycle();
   223→ *   // No need to manually call initializeMCPServer() or stopMCPServer()
   224→ */
   225→export function setupMCPLifecycle(): void {
   226→  // Start server when app is ready
   227→  app.whenReady().then(async () => {
   228→    await initializeMCPServer();
   229→  });
   230→
   231→  // Stop server before quit
   232→  app.on('before-quit', async () => {
   233→    await stopMCPServer();
   234→  });
   235→}
   236→
   237→// ============================================================================
   238→// Export
   239→// ============================================================================
   240→
   241→export default {
   242→  initializeMCPServer,
   243→  stopMCPServer,
   244→  setupMCPLifecycle,
   245→  isMCPServerEnabled,
   246→  isMCPServerRunning,
   247→  getMCPServer,
   248→  getMCPLogLevel
   249→};
