   129→ *     createWindow();
   130→ *   });
   131→ *
   132→ * The server runs in the same process as Electron (embedded mode) and uses stdio transport
   133→ * for communication with the Claude Agent SDK via stdin/stdout.
   134→ *
   135→ * @returns Promise that resolves when server is started or skipped
   136→ * @throws Error if server startup fails
   137→ */
   138→export async function initializeMCPServer(): Promise<void> {
   139→  // Check if MCP server is enabled
   140→  if (!isMCPServerEnabled()) {
   141→    console.log('[MCP] Server not enabled (set ELECTRON_MCP_ENABLED=true to activate)');
   142→    return;
   143→  }
   144→
   145→  // Check if already running
   146→  if (isRunning) {
   147→    console.warn('[MCP] Server already running, skipping initialization');
   148→    return;
   149→  }
   150→
   151→  // Set log level from environment
   152→  const logLevel = getMCPLogLevel();
   153→  if (logLevel !== DEFAULT_LOG_LEVEL) {
   154→    process.env[MCP_LOG_LEVEL_ENV] = logLevel;
   155→    console.log(`[MCP] Log level set to: ${logLevel}`);
   156→  }
   157→
   158→  try {
   159→    console.log('[MCP] Initializing embedded MCP server...');
   160→    console.log('[MCP] Mode: embedded (stdio transport)');
   161→    console.log('[MCP] Transport: stdio (stdin/stdout)');
   162→
   163→    // Create MCP server instance
   164→    mcpServer = new ElectronMCPServer();
   165→
   166→    // Start the server
   167→    await mcpServer.start();
   168→
   169→    isRunning = true;
   170→    console.log('[MCP] ✅ Server started successfully');
   171→    console.log('[MCP] Waiting for JSON-RPC requests via stdin/stdout...');
   172→
   173→  } catch (error) {
   174→    const errorMessage = error instanceof Error ? error.message : String(error);
   175→    console.error('[MCP] ❌ Failed to start server:', errorMessage);
   176→
   177→    if (error instanceof Error && process.env[MCP_LOG_LEVEL_ENV] === 'debug') {
   178→      console.error('[MCP] Stack trace:', error.stack);
   179→    }
   180→
   181→    throw error;
   182→  }
   183→}
   184→
   185→/**
   186→ * Stop the MCP server gracefully.
   187→ *
   188→ * This function is called automatically when the Electron app quits.
   189→ * It closes the stdio transport and cleans up resources.
   190→ *
   191→ * @returns Promise that resolves when server is stopped
   192→ */
   193→export async function stopMCPServer(): Promise<void> {
   194→  if (!isRunning || !mcpServer) {
   195→    return;
   196→  }
   197→
   198→  console.log('[MCP] Stopping server...');
   199→
   200→  try {
   201→    await mcpServer.stop();
   202→  } catch (error) {
   203→    console.error('[MCP] Error during shutdown:', error);
   204→  } finally {
   205→    mcpServer = null;
   206→    isRunning = false;
   207→  }
   208→}
   209→
   210→// ============================================================================
   211→// App Lifecycle Integration
   212→// ============================================================================
   213→
   214→/**
   215→ * Setup automatic MCP server lifecycle management.
   216→ *
   217→ * This function integrates the MCP server with Electron's app lifecycle:
   218→ * - Starts server when app is ready (if enabled)
   219→ * - Stops server when app quits
   220→ *
   221→ * Usage:
   222→ *   setupMCPLifecycle();
   223→ *   // No need to manually call initializeMCPServer() or stopMCPServer()
   224→ */
   225→export function setupMCPLifecycle(): void {
   226→  // Start server when app is ready
   227→  app.whenReady().then(async () => {
   228→    await initializeMCPServer();
   229→  });
   230→
   231→  // Stop server before quit
   232→  app.on('before-quit', async () => {
   233→    await stopMCPServer();
   234→  });
   235→}
   236→
   237→// ============================================================================
   238→// Export
   239→// ============================================================================
   240→
   241→export default {
   242→  initializeMCPServer,
   243→  stopMCPServer,
   244→  setupMCPLifecycle,
   245→  isMCPServerEnabled,
   246→  isMCPServerRunning,
   247→  getMCPServer,
   248→  getMCPLogLevel
   249→};
