    21→/**
    22→ * Defense-in-depth: Dangerous interpreter flags that allow code execution
    23→ * Mirrors backend DANGEROUS_FLAGS to prevent args-based code injection
    24→ */
    25→const DANGEROUS_FLAGS = new Set([
    26→  '--eval', '-e', '-c', '--exec',
    27→  '-m', '-p', '--print',
    28→  '--input-type=module', '--experimental-loader',
