    36→const SHELL_METACHARACTERS = ['&', '|', '>', '<', '^', '%', ';', '$', '`', '\n', '\r'];
    37→
    38→/**
    39→ * Validate that a command is in the safe allowlist
    40→ */
    41→function isCommandSafe(command: string | undefined): boolean {
    42→  if (!command) return false;
    43→  // Reject commands with paths (defense against path traversal)
    44→  if (command.includes('/') || command.includes('\\')) return false;
    45→  return SAFE_COMMANDS.has(command);
