    47→
    48→/**
    49→ * Validate that args don't contain dangerous interpreter flags or shell metacharacters
    50→ */
    51→function areArgsSafe(args: string[] | undefined): boolean {
    52→  if (!args || args.length === 0) return true;
    53→
    54→  // Check for dangerous interpreter flags
    55→  if (args.some(arg => DANGEROUS_FLAGS.has(arg))) return false;
    56→
    57→  // On Windows with shell: true, check for shell metacharacters that could enable injection
    58→  if (isWindows()) {
