   124→      status = 'needs_auth';
   125→      message = response.status === 401 ? 'Authentication required' : 'Access forbidden';
   126→    } else {
   127→      status = 'unhealthy';
   128→      message = `HTTP ${response.status}: ${response.statusText}`;
